class Harvest:
    def __init__(self, farmer, kg):
        self.farmer = farmer
        self.kg = kg

    def __str__(self):
        return f"{self.farmer}: {self.kg} kg"

    def __repr__(self):
        return f"Harvest({self.farmer!r}, {self.kg!r})"

    def __eq__(self, other):
        if not isinstance(other, Harvest):
            return NotImplemented
        return (self.farmer, self.kg) == (other.farmer, other.kg)

    def __lt__(self, other):
        if not isinstance(other, Harvest):
            return NotImplemented
        return self.kg < other.kg


day = [Harvest("Amina", 40), Harvest("Juma", 12.5), Harvest("Wanjiru", 55)]
print(day[0])
print(sorted(day))
print(max(day), Harvest("Juma", 12.5) == day[1])

