class Score:
    def __init__(self, player, points, seconds):
        self.player = player
        self.points = points
        self.seconds = seconds

    def __str__(self):
        return f"{self.player} {self.points} ({self.seconds}s)"

    def __lt__(self, other):
        """'Less' means 'ranks higher', so sorted() lists the best score first."""
        if not isinstance(other, Score):
            return NotImplemented
        if self.points != other.points:
            return self.points > other.points
        return self.seconds < other.seconds


def leaderboard(scores):
    return [str(s) for s in sorted(scores)]
